fn insert(
    oline: &Vec<char>,
    l: usize,
    nl: &Vec<char>,
    p: usize,
    at_pos: usize
) -> Vec<char> {
    // Pre-allocate the resulting vector for efficiency:
    // it will contain exactly l + p characters.
    let mut result = Vec::with_capacity(l + p);

    // 1) Copy the first `at_pos` characters from `oline`
    result.extend_from_slice(&oline[..at_pos]);

    // 2) Insert the first `p` characters from `nl`
    result.extend_from_slice(&nl[..p]);

    // 3) Copy the remaining `l - at_pos` characters from `oline`
    result.extend_from_slice(&oline[at_pos..l]);

    result
}

